with flagged as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval '20' minute then 1 else 0 end as new_group_flag from device_readings), sessions_device_readings as (select *, sum(new_group_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from flagged) select id, device_code, temp_c, pressure, status_bits, firmware, new_group_flag from sessions_device_readings order by device_code nulls first
